import json,itertools
from pathlib import Path
from unittest.mock import patch
import pytest
from lupa.lua54 import LuaRuntime
from tools.script_recovery.convert_quest_unit import UnitConverter
from tools.script_recovery.build_readable_unit import readable_file
ROOT=Path(__file__).resolve().parents[2]
@pytest.fixture(scope='module')
def crowd(tmp_path_factory):
 unit=json.loads((ROOT/'refs/script_recovery/arena/units/Q_Arena.json').read_text())
 c=UnitConverter(ROOT/'refs/script_recovery/arena/translation_unit_typed.json');out=tmp_path_factory.mktemp('crowd-cycle')
 with patch.object(c,'constructor_defaults',return_value={}):c.convert(unit,out)
 draft=(out/'FSE/Arena/Arena.lua').read_text()
 return draft,readable_file(draft)[0]
HARNESS="return function(mode, cycles, hit)\n local frames, registers, adds, removes, updates, reads=0,0,0,0,{},0\n local dead, shown, timers={},{},{}\n local state={NewCrowdPoints=150,NewCrowdBaseLevel=0,NewCrowdLevel=0,\n              OldCrowdBaseLevel=0,OldCrowdLevel=0}\n local limit=mode=='pause' and cycles+4 or mode=='reload' and 2*cycles+5 or mode=='unload' and cycles+2 or cycles+1\n local actor={MsgIsHitBy=function(_,s)assert(s=='');return hit end}\n local q={}\n function q:GetHero()return actor end\n function q:RegisterTimer()registers=registers+1;return registers end\n function q:DeregisterTimer(id)dead[#dead+1]=id end\n function q:SetTimer(id,value)assert(id==1 or id==2);timers[id]=value end\n function q:GetTimer(id)assert(id==1 or id==2);if mode=='pause' then if id==2 and timers[id]==15 then return 0 end;return timers[id] end;return 100 end\n function q:GetStateInt(k)return state[k] or 0 end\n function q:SetStateInt(k,v)state[k]=v end\n function q:GetStateBool(k)assert(k=='PauseCrowdChecker');return mode=='pause' and frames>=2 and frames<=4 end\n function q:IsActiveThreadTerminating()return frames>=limit end\n function q:NewScriptFrame()frames=frames+1;assert(frames<=limit);return frames<limit end\n function q:IsLevelLoaded(k)\n  if k=='ArenaCells' then return false end\n  assert(k=='Arena')\n  return mode=='cancel' or mode=='pause' or frames<=cycles or (mode=='reload' and frames>cycles+2)\n end\n function q:AddQuestInfoBar(...)adds=adds+1;return adds+50 end\n function q:RemoveQuestInfoElement(id)assert(id==51);removes=removes+1 end\n function q:DisplayQuestInfo(value)shown[#shown+1]=value end\n function q:UpdateQuestInfoBar(id,value,a,b)\n  assert(id==adds+50 and a==-1 and b==-1);updates[#updates+1]=value\n end\n function q:GetAllThingsWithScriptName(k)assert(k=='CrowdSoundSource');reads=reads+1;return{}end\n function q:GetAllThingsWithDefName(k)assert(k=='OBJECT_ARENA_AUDIENCE_01');return{}end\n function q:RetailRandModulo(n)assert(n==32768 or n==3);return 0 end\n function q:GetStateString(k)assert(k=='CrowdLoopTags_0_0');return 'MOCK_TAG'end\n function q:GetThingWithScriptName(k)assert(k=='SingleShouter');return actor end\n function q:PlayCriteriaSoundOnThing(who,tag)assert(who==actor and tag=='MOCK_TAG');return 70 end\n function q:ReadGlobalGameData(offset)assert(offset==2664 or offset==2660);return offset==2664 and 10 or 5 end\n function q:AddNewConversation(who,a,b)assert(who==actor and a==false and b==false);return 90 end\n function q:AddPersonToConversation(id,who)assert(id==90 and who==actor)end\n function q:AddLineToConversation(id,line,who,listener,last)assert(id==90 and line=='TEXT_QST_005_ARENA_CROWD_CHEER_WASPS' and who==actor and listener==actor and last==false)end\n function q:IsSoundPlaying(handle)return false end\n function q:StopSound(handle)end\n function q:SetStateFloat(k,v)state[k]=v end\n function q:RetailResources()return{}end\n setmetatable(q,{__index=function(_,name)return function(...)error('unexpected '..name)end end})\n debug.sethook(function()error('instruction budget')end,'',100000)\n CrowdChecker(q)\n debug.sethook()\n local iterations=mode=='reload' and 2*cycles+1 or cycles\n assert(frames==limit,'frames '..frames..' expected '..limit)\n assert(registers==2 and #dead==2 and dead[1]==2 and dead[2]==1,'timer lifetime')\n assert(adds==(mode=='reload' and 2 or 1) and reads==adds,'repeated initialization')\n assert(removes==((mode=='cancel' or mode=='pause') and 0 or 1),'HUD unload')\n assert(#updates==iterations,'iterations '..#updates..' expected '..iterations)\n assert(state.NewCrowdPoints==150-(mode=='pause' and 4 or 0)-(hit and 5*iterations or 0),'points')\n for i,value in ipairs(updates)do assert(value==150-((mode=='pause' and i>1) and 4 or 0)-(hit and 5*(i-1) or 0))end\n return frames..':'..adds..':'..removes..':'..state.NewCrowdPoints\nend"
@pytest.mark.parametrize('style',[0,1])
@pytest.mark.parametrize('mode,cycles,hit',list(itertools.product(('cancel','unload','reload','pause'),(1,2,4,7),(False,True))))
def test_actual_crowd_checker_cycles_pause_and_region_cleanup(crowd,style,mode,cycles,hit):
 lua=LuaRuntime();lua.execute(crowd[style]);check=lua.execute(HARNESS)
 assert check(mode,cycles,hit)
